/* Fleet home-head context line (design.md `page-header`).
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * nothing here varies between apps. Normalized from app-launcher's
 * `renderHeadStatus` (home-head.js) and home-automation's (head-status.js),
 * which had drifted in two places; see home-head/README.md "Context line".
 *
 * Pairs with home-head.css (`.head-exception[data-tone]`). The context line is
 * live and names only the exceptions, each in its tone's `*-text`, at most two
 * parts (about 22 characters at 390px), and falls back to a plain muted fact
 * when nothing is wrong. Pure render over what the caller computed: it keeps
 * no state and reads nothing but the slot it is handed. Text goes in with
 * `textContent`, never as HTML.
 */

'use strict';

// The most exceptions one header line shows (about 22 characters at 390px).
export const HEAD_MAX_PARTS = 2;

// Severity order (design.md `page-header`: "offline or failed first"). The sort
// is stable, so parts of one tone keep the caller's order; a tone the CSS does
// not colour (neutral, or anything unknown) sorts last.
const TONE_RANK = { danger: 0, attention: 1 };

function toneRank(tone) {
  return tone in TONE_RANK ? TONE_RANK[tone] : 2;
}

/**
 * Render one context line into a header's `.status` slot.
 *
 * @param {HTMLElement|null|undefined} el  the `.status` slot; absent = no-op,
 *        so a header without one needs no guard at the call site.
 * @param {Array<{text: string, tone?: string}>|null|undefined} exceptions
 *        what is wrong, `tone` one of `danger` | `attention` | `neutral`.
 *        Entries without text are ignored.
 * @param {string} [fallback]  the plain muted fact shown when nothing is wrong.
 */
export function renderHeadStatus(el, exceptions, fallback) {
  if (!el) return;
  const shown = (exceptions || [])
    .filter(function (x) { return x && x.text; })
    .sort(function (a, b) { return toneRank(a.tone) - toneRank(b.tone); })
    .slice(0, HEAD_MAX_PARTS);
  el.textContent = '';
  if (!shown.length) {
    el.textContent = fallback || '';
    delete el.dataset.tone;
    return;
  }
  shown.forEach(function (x, i) {
    if (i) el.appendChild(document.createTextNode(' · '));
    const part = document.createElement('span');
    part.className = 'head-exception';
    part.dataset.tone = x.tone || 'neutral';
    part.textContent = x.text;
    el.appendChild(part);
  });
  // The worst part's tone, for an app hook on the slot itself; the colour is
  // always the part's own.
  el.dataset.tone = shown[0].tone || 'neutral';
}
